from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P05','AP_READY=1','BAD_SNAPSHOT=00','BAD_CYCLE_DONE=1','BAD_STALE_ACCEPT=1','GOOD_SNAPSHOT=0000','GOOD_CYCLE_DONE=1','GOOD_EPOCH=01','GOOD_STALE_ACCEPT=0','GOOD_FRESH_ACCEPT=1','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1']),'bad_aba_accepts_stale':all(x in trace for x in ['BAD_SNAPSHOT=00','BAD_CYCLE_DONE=1','BAD_STALE_ACCEPT=1']),'versioned_compare_rejects_stale':all(x in trace for x in ['GOOD_SNAPSHOT=0000','GOOD_EPOCH=01','GOOD_STALE_ACCEPT=0','GOOD_FRESH_ACCEPT=1'])};out={'format':'C005_P05_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
